SET NOCOUNT ON;
INSERT INTO [Orders] ([ID], [DateCreated], [DateDeleted], [DateOrderd], [DateRejected], [DateUpdated], [IsDelete], [ShipAddress], [ShipEmail], [ShipName], [ShipNumberPhone], [Status], [StatusPayment], [TotalPrice], [UserID])
VALUES (@p0, @p1, @p2, @p3, @p4, @p5, @p6, @p7, @p8, @p9, @p10, @p11, @p12, @p13, @p14);
SELECT [Sort]
FROM [Orders]
WHERE @@ROWCOUNT = 1 AND [ID] = @p0;
